from pathlib import Path
p=Path('/home/ubuntu/global-ai-coach/client/src/pages/Home.tsx')
s=p.read_text()
s=s.replace('import { calculateSwipeSteps, confidenceForSampleSize, swipeDirection, undoRangePayload } from "@/lib/chartInteractions";', 'import { boundedWindowStart, calculateSwipeSteps, confidenceForSampleSize, easeOutCubic, swipeDirection, undoRangePayload } from "@/lib/chartInteractions";', 1)
s=s.replace('  const maxStart = Math.max(0, series.length - windowSize);\n  const visibleSeries', '  const maxStart = Math.max(0, series.length - windowSize);\n  function animateWindowTo(target: number) {\n    const from = windowStart;\n    const destination = Math.max(0, Math.min(maxStart, target));\n    const startedAt = performance.now();\n    function frame(now: number) {\n      const progress = Math.min(1, (now - startedAt) / 220);\n      setWindowStart(Math.round(from + (destination - from) * easeOutCubic(progress)));\n      if (progress < 1) requestAnimationFrame(frame);\n    }\n    requestAnimationFrame(frame);\n  }\n  const visibleSeries', 1)
s=s.replace('const steps = calculateSwipeSteps(dx, performance.now() - startTouch.startedAt, maxStart); setWindowStart((value) => Math.max(0, Math.min(maxStart, value + swipeDirection(dx) * steps)));', 'const steps = calculateSwipeSteps(dx, performance.now() - startTouch.startedAt, maxStart); animateWindowTo(boundedWindowStart(windowStart, swipeDirection(dx) * steps, maxStart));', 1)
s=s.replace('<Button variant="outline" size="sm" onClick={() => { setZoom((value) => Math.min(4, value + 1)); setWindowStart(0); }} aria-label="Zoom in trend chart">+</Button><TrendingUp', '<Button variant="outline" size="sm" onClick={() => { setZoom((value) => Math.min(4, value + 1)); setWindowStart(0); }} aria-label="Zoom in trend chart">+</Button><Button variant="ghost" size="sm" onClick={() => { setZoom(1); animateWindowTo(0); setHovered(null); }} aria-label="Reset trend chart view">Reset view</Button><TrendingUp', 1)
p.write_text(s)
